        var m = mins % 60;
        var suffix = h >= 12 ? 'pm' : 'am';
        var h12 = h % 12;
        if (h12 === 0) { h12 = 12; }
        return h12 + (m ? ':' + (m < 10 ? '0' : '') + m : '') + suffix;
      }

      function fmtRupees(n) {
        return '₹' + n.toLocaleString('en-IN');
      }

      function readQty(el) {
        var n = parseInt(el.value, 10);
        if (isNaN(n) || n < 0) { return 0; }
        if (n > 20) { return 20; }
