    .bl-order-error { margin: .35rem 0 0; font-size: .9rem; color: #b3261e; min-height: 0; }
    .bl-order-error:empty { display: none; }
    .bl-order-submit {
      display: block;
      width: 100%;
      padding: .85rem 1.25rem;
      font: inherit;
      font-weight: 600;
      color: #fff;
      background: var(--bl-accent);
      border: 0;
      border-radius: var(--bl-radius);
      cursor: pointer;
    }
    .bl-order-submit:hover, .bl-order-submit:focus { background: #6f3b19; }
    .bl-order-confirm {
      max-width: 36rem;
      margin-top: 1rem;
      padding: 1rem;
      background: #eaf5ea;
      border: 1px solid #b7d9b7;
      border-radius: var(--bl-radius);
    }
    .bl-order-confirm[hidden] { display: none; }
    .bl-order-confirm p { margin-bottom: .5rem; }
    .bl-order-confirm p:last-child { margin-bottom: 0; }
    @media (min-width: 768px) {
      .bl-order-form { padding: 1.5rem; }
      .bl-order-submit { width: auto; }
    }
  </style>

  <script>
    (function () {
      var form = document.getElementById('bl-order-form');
      if (!form) { return; }

      var nameEl = document.getElementById('bl-order-name');
      var phoneEl = document.getElementById('bl-order-phone');
      var timeEl = document.getElementById('bl-order-time');
      var totalEl = document.getElementById('bl-order-total');
      var hintEl = document.getElementById('bl-order-hint');
      var confirmBox = document.getElementById('bl-order-confirm');
      var confirmText = document.getElementById('bl-order-confirm-text');
      var waLink = document.getElementById('bl-order-wa-link');
      var qtyEls = form.querySelectorAll('.bl-order-qty');
      var errs = {
        name: document.getElementById('bl-order-name-err'),
        phone: document.getElementById('bl-order-phone-err'),
        items: document.getElementById('bl-order-items-err'),
        time: document.getElementById('bl-order-time-err')
      };

      var WA_NUMBER = '919845000000';
      var DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

      // Opening hours in minutes from midnight. Mon-Fri 8am-10pm, Sat-Sun 9am-11pm.
      function hoursFor(day) {
        if (day === 0 || day === 6) { return { open: 9 * 60, close: 23 * 60 }; }
        return { open: 8 * 60, close: 22 * 60 };
      }

      function fmtTime(mins) {
        var h = Math.floor(mins / 60);
        var m = mins % 60;
        var suffix = h >= 12 ? 'pm' : 'am';
        var h12 = h % 12;
        if (h12 === 0) { h12 = 12; }
        return h12 + (m ? ':' + (m < 10 ? '0' : '') + m : '') + suffix;
      }

      function fmtRupees(n) {
        return '₹' + n.toLocaleString('en-IN');
      }

      function readQty(el) {
        var n = parseInt(el.value, 10);
        if (isNaN(n) || n < 0) { return 0; }
        if (n > 20) { return 20; }
        return n;
      }

      function computeTotal() {
        var total = 0;
        for (var i = 0; i < qtyEls.length; i++) {
          total += readQty(qtyEls[i]) * parseInt(qtyEls[i].getAttribute('data-price'), 10);
        }
        return total;
      }

      function updateTotal() {
        totalEl.textContent = fmtRupees(computeTotal());
      }

      var todayIdx = new Date().getDay();
      var todayHours = hoursFor(todayIdx);
      hintEl.textContent = 'Today (' + DAY_NAMES[todayIdx] + ') we are open ' + fmtTime(todayHours.open) + ' to ' + fmtTime(todayHours.close) + '. Pick a time in that window.';
      timeEl.setAttribute('min', pad(Math.floor(todayHours.open / 60)) + ':' + pad(todayHours.open % 60));
      timeEl.setAttribute('max', pad(Math.floor(todayHours.close / 60)) + ':' + pad(todayHours.close % 60));

      function pad(n) { return (n < 10 ? '0' : '') + n; }

      function setError(key, input, msg) {
        errs[key].textContent = msg || '';
        if (input) {
          if (msg) { input.setAttribute('aria-invalid', 'true'); }
          else { input.removeAttribute('aria-invalid'); }
        }
      }

      function parseTime(value) {
        var m = /^(\d{1,2}):(\d{2})/.exec(value || '');
        if (!m) { return null; }
        var h = parseInt(m[1], 10);
        var mi = parseInt(m[2], 10);
        if (h > 23 || mi > 59) { return null; }
        return h * 60 + mi;
      }

      function validate() {
        var ok = true;
        var firstBad = null;

        var name = nameEl.value.trim();
        if (!name) {
          setError('name', nameEl, 'Please enter your name.');
          ok = false; firstBad = firstBad || nameEl;
        } else { setError('name', nameEl, ''); }

        var digits = phoneEl.value.replace(/[\s\-+()]/g, '');
        if (!/^(91)?[6-9]\d{9}$/.test(digits)) {
          setError('phone', phoneEl, 'Enter a valid 10 digit mobile number.');
          ok = false; firstBad = firstBad || phoneEl;
        } else { setError('phone', phoneEl, ''); }

        if (computeTotal() <= 0) {
          setError('items', null, 'Choose at least one item.');
          ok = false; firstBad = firstBad || qtyEls[0];
        } else { setError('items', null, ''); }

        var mins = parseTime(timeEl.value);
        var hours = hoursFor(new Date().getDay());
        if (mins === null) {
          setError('time', timeEl, 'Please choose a pickup time.');
          ok = false; firstBad = firstBad || timeEl;
        } else if (mins < hours.open || mins > hours.close) {
          setError('time', timeEl, 'Pickup must be between ' + fmtTime(hours.open) + ' and ' + fmtTime(hours.close) + ' today.');
          ok = false; firstBad = firstBad || timeEl;
        } else { setError('time', timeEl, ''); }

        if (firstBad && typeof firstBad.focus === 'function') { firstBad.focus(); }
        return ok;
      }

      function buildMessage(name, phone, mins, total) {
        var lines = [];
        lines.push('New Brew Lab pickup order');
        lines.push('Name: ' + name);
        lines.push('Phone: ' + phone);
        lines.push('Items:');
        for (var i = 0; i < qtyEls.length; i++) {
          var q = readQty(qtyEls[i]);
          if (q > 0) {
            var price = parseInt(qtyEls[i].getAttribute('data-price'), 10);
            lines.push('- ' + qtyEls[i].getAttribute('data-name') + ' x ' + q + ' (' + fmtRupees(q * price) + ')');
          }
        }
        lines.push('Pickup time: ' + fmtTime(mins) + ' today (' + DAY_NAMES[new Date().getDay()] + ')');
        lines.push('Total: ' + fmtRupees(total));
        lines.push('Payment at pickup.');
        return lines.join('\n');
      }

      for (var i = 0; i < qtyEls.length; i++) {
        qtyEls[i].addEventListener('input', updateTotal);
        qtyEls[i].addEventListener('change', function () {
          // Normalise odd values (blank, negative, over 20) after editing.
          this.value = String(readQty(this));
          updateTotal();
        });
      }

      form.addEventListener('submit', function (ev) {
        ev.preventDefault();
        if (!validate()) {
          confirmBox.hidden = true;
          return;
        }
        var name = nameEl.value.trim();
        var phone = phoneEl.value.trim();
        var mins = parseTime(timeEl.value);
        var total = computeTotal();
        var url = 'https://wa.me/' + WA_NUMBER + '?text=' + encodeURIComponent(buildMessage(name, phone, mins, total));

        waLink.setAttribute('href', url);
        confirmText.textContent = 'Thanks, ' + name + '. Your order for ' + fmtRupees(total) + ' is ready to send on WhatsApp for pickup at ' + fmtTime(mins) + '. Payment is at pickup.';
        confirmBox.hidden = false;

        var w = null;
        try { w = window.open(url, '_blank'); } catch (e) { w = null; }
        if (w) { try { w.opener = null; } catch (e2) { /* ignore */ } }

        if (typeof confirmBox.focus === 'function') { confirmBox.focus(); }
      });

      updateTotal();
    })();
  </script>
</section>
<!-- J2:W-3 end -->
